code_es:
Proceso SumaDeMatriz
    Dimension datos[2, 3] Como Entero;
    Definir fila Como Entero;
    Definir columna Como Entero;
    Definir total Como Entero;
    Para fila <- 0 Hasta 1 Con Paso 1 Hacer
        Para columna <- 0 Hasta 2 Con Paso 1 Hacer
            Leer datos[fila, columna];
        FinPara
    FinPara
    total <- 0;
    Para fila <- 0 Hasta 1 Con Paso 1 Hacer
        Para columna <- 0 Hasta 2 Con Paso 1 Hacer
            total <- total + datos[fila, columna];
        FinPara
    FinPara
    Escribir total;
FinProceso

code_en:
algorithm SumOfMatrix
    dimension data[2, 3] as integer;
    define row as integer;
    define column as integer;
    define total as integer;
    for row <- 0 to 1 step 1 do
        for column <- 0 to 2 step 1 do
            read data[row, column];
        endFor
    endFor
    total <- 0;
    for row <- 0 to 1 step 1 do
        for column <- 0 to 2 step 1 do
            total <- total + data[row, column];
        endFor
    endFor
    write total;
endAlgorithm

